import * as THREE from 'three';
export function createGunEffects(scene){
 const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const c=canvas.getContext('2d'),gradient=c.createRadialGradient(32,32,0,32,32,32);gradient.addColorStop(0,'rgba(255,255,255,.9)');gradient.addColorStop(.35,'rgba(255,255,255,.55)');gradient.addColorStop(1,'rgba(255,255,255,0)');c.fillStyle=gradient;c.fillRect(0,0,64,64);const texture=new THREE.CanvasTexture(canvas);
 const pool=Array.from({length:48},()=>{const material=new THREE.SpriteMaterial({map:texture,transparent:true,depthWrite:false}),mesh=new THREE.Sprite(material);mesh.visible=false;scene.add(mesh);return {mesh,life:0,total:1,velocity:new THREE.Vector3(),size:1,fire:false};});let cursor=0;
 function puff(position,velocity,size,life,fire=false){const p=pool[cursor++%pool.length];p.mesh.position.copy(position);p.velocity.copy(velocity);p.life=p.total=life;p.size=size;p.fire=fire;p.mesh.material.color.set(fire?'#ffbd61':'#ada99f');p.mesh.material.blending=fire?THREE.AdditiveBlending:THREE.NormalBlending;p.mesh.visible=true;}
 return {muzzle(position,aim){for(let i=0;i<3;i++)puff(position,new THREE.Vector3((Math.random()-.5)*.17,.25+Math.random()*.12,(Math.random()-.5)*.17).addScaledVector(aim,.25),.09,.45+Math.random()*.3);},impact(position,explosion){if(explosion){puff(position,new THREE.Vector3(),2.8,.22,true);for(let i=0;i<14;i++){const a=i/14*Math.PI*2;puff(position,new THREE.Vector3(Math.cos(a)*(1+Math.random()*2),.6+Math.random()*1.3,Math.sin(a)*(1+Math.random()*2)),.6,1.3+Math.random()*.7,i<5);}}else for(let i=0;i<2;i++)puff(position,new THREE.Vector3((Math.random()-.5)*.35,.25,(Math.random()-.5)*.35),.1,.4);},update(dt){for(const p of pool){if(p.life<=0)continue;p.life-=dt;p.mesh.visible=p.life>0;const age=1-p.life/p.total;p.mesh.position.addScaledVector(p.velocity,dt);p.velocity.multiplyScalar(Math.exp(-dt*1.4));p.mesh.scale.setScalar(p.size*(1+age*(p.fire?1.4:3)));p.mesh.material.opacity=(p.fire?.85:.25)*Math.sin(Math.PI*Math.min(1,age+.15))*Math.max(0,1-age);}}};
}
